create table if not exists public.dd_reconciliation_checkpoints (id uuid primary key default gen_random_uuid(), scope_code text not null unique, scope_name text not null, evidence_sources text not null, record_count integer, provider_evidence_count integer, canonical_count integer, pending_count integer, conflict_count integer, decision text not null, next_action text not null, status text not null default 'LOCKED_CHECKPOINT', created_at timestamptz not null default now(), updated_at timestamptz not null default now()); insert into public.dd_reconciliation_checkpoints(scope_code,scope_name,evidence_sources,record_count,provider_evidence_count,canonical_count,pending_count,conflict_count,decision,next_action) values ('DIV01','Division 01 — Home, Pet, Plant & Household Support','DANI Master Service Universe; current services registry; historical Division 01 evidence; Master Pricing Architecture; Resident Guide/Welcome evidence; Vendor Packet evidence; provider service universe',49,0,(select count(*) from dd_master_service_universe where division='01' and lifecycle_status='CANONICAL_ACTIVE'),(select count(*) from dd_master_service_universe where division='01' and lifecycle_status='PENDING_RECONCILIATION'),(select count(*) from dd_master_service_universe where division='01' and lifecycle_status='ABSORBED_REDIRECTED'),'DIVISION_01_EVIDENCE_CAPTURED_PROVIDER_GAP_NOT_FOUND','Normalize 01-A through 01-G taxonomy; resolve duplicate/redirected services; reconcile packet/guide evidence; attach approved market pricing only after service decisions; then map fulfillment/provider coverage and proceed to Division 02') on conflict(scope_code) do update set evidence_sources=excluded.evidence_sources,record_count=excluded.record_count,provider_evidence_count=excluded.provider_evidence_count,canonical_count=excluded.canonical_count,pending_count=excluded.pending_count,conflict_count=excluded.conflict_count,decision=excluded.decision,next_action=excluded.next_action,status='LOCKED_CHECKPOINT',updated_at=now();